/* Signature Uyghur Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Aygulnur": "From ay (moon) + gul (flower) + nur (light): 'moon-flower light'.", "Erkinay": "From erkin (free) + ay (moon): 'free moon'.", "Dilnurgul": "From dil (heart) + nur (light) + gul (flower).", "Altunay": "From altun (gold) + ay (moon): 'golden moon'.", "Yultuzgul": "From yultuz (star) + gul (flower): 'star flower'.", "Bahargul": "From bahar (spring) + gul (flower): 'spring flower'.", "Aynurov": "Signature surname in the -ov style built on Aynur.", "Erkinzade": "From erkin + Persian -zade (child of): Signature surname, 'child of freedom'.", "Gulnarov": "Signature surname built on gul + nar.", "Aytmatov-style": "Signature surname pattern note: Turkic root + Slavic -ov, as in the region's Soviet-era forms."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Aygulnur';
console.log(lookup(q));

